        using var sync = new TrackingStream();
        _sut.ComplexEntity.Where(x => x.Id == 1).Select(x => new { x.Id })
            .WriteCsv(sync, null, TestContext.Current.CancellationToken);

        sync.WasDisposed.Should().BeFalse();
        sync.CanRead.Should().BeTrue();
